<?php require_once '../includes/functions.php';require_staff();$pdo=db();$students=$pdo->query("SELECT u.id,u.name,u.email,u.created_at,COUNT(a.id) attempts,COALESCE(ROUND(AVG(a.percentage),1),0) average FROM users u LEFT JOIN attempts a ON a.user_id=u.id WHERE u.role='student' GROUP BY u.id ORDER BY u.created_at DESC")->fetchAll();
$sql="SELECT a.id,u.name student,q.title,a.score,a.total_questions,a.percentage,a.completed_at FROM attempts a JOIN users u ON u.id=a.user_id JOIN quizzes q ON q.id=a.quiz_id";$params=[];if(user()['role']==='teacher'){$sql.=' WHERE q.created_by=?';$params[] = user()['id'];}$sql.=' ORDER BY a.completed_at DESC LIMIT 100';$s=$pdo->prepare($sql);$s->execute($params);$results=$s->fetchAll();$pageTitle='Students and Results';require '../includes/header.php';?>
<h1>Students</h1><div class="table-wrap"><table><tr><th>Name</th><th>Email</th><th>Attempts</th><th>Average</th><th>Joined</th></tr><?php foreach($students as $u):?><tr><td><?=e($u['name'])?></td><td><?=e($u['email'])?></td><td><?=$u['attempts']?></td><td><?=$u['average']?>%</td><td><?=date('d M Y',strtotime($u['created_at']))?></td></tr><?php endforeach;?></table></div><h2>Quiz Results</h2><div class="table-wrap"><table><tr><th>Student</th><th>Quiz</th><th>Score</th><th>Percentage</th><th>Date</th></tr><?php foreach($results as $r):?><tr><td><?=e($r['student'])?></td><td><?=e($r['title'])?></td><td><?=$r['score']?> / <?=$r['total_questions']?></td><td><?=$r['percentage']?>%</td><td><?=date('d M Y H:i',strtotime($r['completed_at']))?></td></tr><?php endforeach;?></table></div>
<?php require '../includes/footer.php';?>
